sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({ api, helpers }) {
    // Get the initial data
    var data = api.data.top_pro_from_top_pub_1.output.top_products;
    var selectedPublishers = api.data.get_filter_publisher_1.output;
    var searchTerm = api.state.searchInput;

    // Debug logs
    console.log("Initial data length:", data.length);
    console.log("searchTerm", searchTerm);
    console.log("selectedPublisers", selectedPublishers);

    // Only take the first half of the data to remove duplicates
    data = data.slice(0, data.length/2);

    // Extract publisher IDs and labels
    var selectedPublisherIds = selectedPublishers.flat().map(publisher => publisher.id);
    var selectedPublisherLabels = selectedPublishers.flat().map(publisher => publisher.label);

    // Filter by publishers
    var filteredData = data;
    if (selectedPublishers && selectedPublishers.length > 0) {
        filteredData = data.filter(item => {
            return selectedPublisherIds.includes(item.publisher) || 
                   selectedPublisherLabels.includes(item.publisher);
        });
    }

    // Apply search filter if exists
    if (searchTerm && searchTerm.trim()) {
        filteredData = filteredData.filter(item => {
            return Object.values(item).some(value =>
                String(value).toLowerCase().includes(searchTerm.toLowerCase())
            );
        });
    }

    // Get pagination details
    var currentPage = api.state.currentPage || 1;
    var recordsPerPage = api.state.recordsPerPage || 10;
    var startIndex = (currentPage - 1) * recordsPerPage;
    var endIndex = startIndex + recordsPerPage;

    // Store pagination info in state
    api.state.totalRecords = filteredData.length;
    api.state.totalPages = Math.ceil(filteredData.length / recordsPerPage);

    // Get the final paginated data
    var paginatedData = filteredData.slice(startIndex, endIndex);

    // Return only the paginated data
    return paginatedData;
}
